import React from 'react';
const PlanPage = () => {
    return (
        <div className='plan-page'>
            <div className="container mx-auto">
                <div className="flex flex-col items-center justify-center min-h-screen">
                    <h1 className="text-4xl font-bold mb-4">Lên kế hoạch cho chuyến đi của bạn</h1>
                    <p className="text-lg mb-8">Chọn các địa điểm và lên lịch trình cho chuyến đi của bạn.</p>
                    <ItineraryModule />
                </div>
            </div>

        </div>
    );
};

export default PlanPage;
